import{_ as e,o as a,c as s,a2 as r}from"./chunks/framework.ChTAMbUy.js";const u=JSON.parse('{"title":"Gateway Usage","description":"","frontmatter":{},"headers":[],"relativePath":"1.10/platform/gateway_usage.md","filePath":"versions/1.10/platform/gateway_usage.md","lastUpdated":1795294041000}'),o={name:"1.10/platform/gateway_usage.md"};function n(l,t,i,d,h,g){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="gateway-usage" tabindex="-1">Gateway Usage <a class="header-anchor" href="#gateway-usage" aria-label="Permalink to &quot;Gateway Usage&quot;">​</a></h1><p><strong>Gateway Usage</strong> shows the calls that went through <a href="./agent_gateway.html">Agent Gateway</a> in the selected workspace: calls to models, MCP servers, memory stores, agents, and other gateway routes. Use it to find out who or what is calling a workspace service, which credential the calls used, how many failed, and what the LLM calls are estimated to cost.</p><p>Open <strong>Gateway Usage</strong> under <strong>Monitoring</strong> in the sidebar and select the workspace.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/gateway-usage/gateway-usage-summary-framed.png" alt="Gateway Usage summary with tiles, the source table, and the call trend" loading="lazy"></p><p>Calls that bypass Agent Gateway, for example a workload calling a model&#39;s cluster-internal service address directly, are not counted. Prompts, responses, and tool arguments are never shown.</p><h2 id="who-sees-what" tabindex="-1">Who Sees What <a class="header-anchor" href="#who-sees-what" aria-label="Permalink to &quot;Who Sees What&quot;">​</a></h2><p>Any member of the workspace, including read-only members, can open the page. All members see external model grant calls, internal calls, token calls, and calls without valid credentials. For API key calls, regular users see only the keys they own; platform administrators see every key in the workspace.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>Every call belongs to exactly one source, based on how it was authenticated:</p><table tabindex="0"><thead><tr><th>Source</th><th>Calls</th></tr></thead><tbody><tr><td><strong>API keys</strong></td><td>Calls made with an <a href="./api_keys.html">API key</a> of this workspace.</td></tr><tr><td><strong>External model grants</strong></td><td>Agents and workloads using an <a href="./../admin/external_models.html">external model</a> granted to the workspace. They use the workspace&#39;s built-in credential and need no API key.</td></tr><tr><td><strong>Internal calls</strong></td><td>Platform services calling each other inside the cluster without a key, for example an agent calling a self-hosted model, an MCP server, or another agent. See <a href="./agent_gateway.html#public-vs-internal-traffic">Public vs. Internal Traffic</a>.</td></tr><tr><td><strong>Token calls</strong></td><td>Calls signed in with a user account, or with the token of a workspace notebook or pipeline, for example to sandboxes. A token call can still fail after sign-in, for example with <code>403</code>.</td></tr><tr><td><strong>Calls without valid credentials</strong></td><td>Calls with a missing, invalid, or revoked API key or token.</td></tr></tbody></table><h2 id="read-the-summary" tabindex="-1">Read the Summary <a class="header-anchor" href="#read-the-summary" aria-label="Permalink to &quot;Read the Summary&quot;">​</a></h2><p>Use the controls at the top of the page:</p><ul><li><strong>Source</strong>: <strong>All sources</strong> or a single source.</li><li><strong>Time window</strong>: <strong>Last hour</strong>, <strong>Last 24 hours</strong> (default), <strong>Last 7 days</strong>, or <strong>Max (N days)</strong>. N is set by the platform administrator and defaults to 10 days.</li><li><strong>Refresh</strong>: reloads the numbers.</li></ul><p>The summary has four tiles:</p><table tabindex="0"><thead><tr><th>Tile</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Calls</strong></td><td>All calls through Agent Gateway in the window. The note shows how many of them were <strong>LLM calls</strong>: calls to language, embedding, and rerank models.</td></tr><tr><td><strong>Failed calls</strong></td><td>Calls that returned HTTP 400–599, with their share of all calls. Redirects count as successful.</td></tr><tr><td><strong>LLM tokens</strong></td><td>Input and output tokens of the LLM calls.</td></tr><tr><td><strong>Estimated cost</strong></td><td>Cost of the LLM calls at the model prices that were set when each call was made. <strong>Some calls have no price set</strong> means the total is partial.</td></tr></tbody></table><p>To follow one key or caller over time, select <strong>API keys</strong>, <strong>External model grants</strong>, or <strong>Internal calls</strong> as the source, then pick the key or caller for the <strong>Call trend</strong>. A link to the page keeps the selection.</p><p>If the window starts before the oldest retained gateway logs, the page shows <strong>Logs start at …; numbers for this window are partial.</strong></p><h2 id="break-down-usage" tabindex="-1">Break Down Usage <a class="header-anchor" href="#break-down-usage" aria-label="Permalink to &quot;Break Down Usage&quot;">​</a></h2><p>Use the tabs below the summary to find which workload, key, or route generates calls or cost. A link to the page keeps the selected source and tab.</p><ul><li><strong>By caller</strong>: one row per calling workload, with its sources, calls, tokens, and estimated cost. The caller is the workload&#39;s Kubernetes ServiceAccount, for example <code>my-agent</code>; hover to see the full identity, such as <code>cluster.local/ns/&lt;workspace&gt;/sa/my-agent</code>. Calls through the public endpoint show <strong>Not recorded (public endpoint)</strong>, because the gateway does not record which workload sent them; they can come from outside or inside the cluster.</li><li><strong>By API key</strong>: one row per API key, with its owner, calls, LLM calls, failures, tokens, estimated cost, and <strong>Last active</strong>. A deleted key that still has recorded calls shows as <strong>Historical</strong> and cannot open Activity. Under any source other than <strong>API keys</strong>, the tab shows <strong>Show API keys</strong> instead.</li><li><strong>Details</strong>: one row per credential, caller, and model or route, with the status of the calls.</li></ul><p>Calls that platform controllers make on behalf of agents, such as kagent discovering MCP tools, are <strong>background calls</strong>. They are left out of the totals, the trend, and the source table. Select <strong>Show</strong> in the background-calls note, for example <strong>background calls by kagent-controller</strong>, to list them in <strong>By caller</strong> and <strong>Details</strong>.</p><p>Hover a status label such as <strong>Unauthorized</strong> to see the exact HTTP codes. Expand <strong>How usage is counted</strong> at the bottom of the page for the definitions of all labels.</p><h2 id="inspect-individual-calls" tabindex="-1">Inspect Individual Calls <a class="header-anchor" href="#inspect-individual-calls" aria-label="Permalink to &quot;Inspect Individual Calls&quot;">​</a></h2><p>Select <strong>Activity</strong> in a row to list the individual calls behind it:</p><ul><li>From <strong>By API key</strong> or <strong>Details</strong>, Activity lists the calls made with that credential. The same dialog opens from <strong>API Keys &gt; Actions &gt; Activity</strong>. See <a href="./api_keys.html#request-activity">API Keys: Request Activity</a>.</li><li>From <strong>By caller</strong>, Activity lists the calls that caller made in this workspace. The caller is fixed; the dialog shows its identity and source instead of a caller filter.</li></ul><p>Both kinds of Activity offer the same time window, <strong>HTTP status</strong>, and <strong>Request model</strong> filters, paging with <strong>Older</strong> and <strong>Newer</strong>, and <strong>Export CSV</strong> for the current page.</p><h2 id="traffic-on-resource-pages" tabindex="-1">Traffic on Resource Pages <a class="header-anchor" href="#traffic-on-resource-pages" aria-label="Permalink to &quot;Traffic on Resource Pages&quot;">​</a></h2><p>Resource detail pages show the calls a resource received, using the same sources and definitions:</p><table tabindex="0"><thead><tr><th>Page</th><th>Where</th></tr></thead><tbody><tr><td><a href="./../agentops/llm_serving.html">LLM Serving</a> and <a href="./../mlops/model_serving.html">Model Serving</a> models</td><td><strong>Traffic</strong> tab</td></tr><tr><td><a href="./../agentops/mcp_servers.html">MCP servers</a></td><td><strong>Traffic</strong> tab</td></tr><tr><td><a href="./../agentops/memory_stores.html">Memory stores</a></td><td><strong>Traffic</strong> tab</td></tr><tr><td><a href="./../agentops/agents.html">Agents</a></td><td><strong>Overview</strong> &gt; <strong>Traffic</strong> (calls to the agent) and <strong>Usage</strong> (calls the agent made)</td></tr><tr><td><a href="./../admin/external_models.html">External Models</a> grants and granted Model Configurations</td><td><strong>View Traffic</strong> on the grant, or the Model Configuration&#39;s detail page</td></tr></tbody></table><p>An agent&#39;s <strong>Usage</strong> section counts the model and tool calls made by the agent&#39;s ServiceAccount. Agents that run as the same ServiceAccount share these totals. <strong>Open Gateway Usage</strong> opens this page for the workspace.</p><p><strong>Traffic telemetry unavailable</strong> means the numbers could not be read; it does not mean that there were no calls.</p><h2 id="reading-the-numbers-correctly" tabindex="-1">Reading the Numbers Correctly <a class="header-anchor" href="#reading-the-numbers-correctly" aria-label="Permalink to &quot;Reading the Numbers Correctly&quot;">​</a></h2><ul><li>Counts, tokens, and costs come from Agent Gateway access logs, kept for 10 days by default. Costs are estimates, not billing records.</li><li>A price applies only to calls made after it was set. See <a href="./../admin/llm_usage.html#pricing-and-historical-usage">Pricing and Historical Usage</a>.</li><li>Calls without an API key belong to the workspace named in the request path or, failing that, to the namespace of the calling workload. Calls that match no workspace appear only in the platform-wide views for administrators: <a href="./system_status.html#agent-gateway-traffic">System Status</a> and <a href="./../admin/llm_usage.html">LLM Usage and Cost</a>.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./api_keys.html">API Keys</a></li><li><a href="./agent_gateway.html">Agent Gateway</a></li><li><a href="./../admin/llm_usage.html">LLM Usage and Cost</a></li><li><a href="./system_status.html">System Status</a></li><li><a href="./../admin/operations_runbooks.html#auditing-llm-usage">Auditing LLM Usage</a></li></ul>',35)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
